SELECT c.id, c.name, p.customer_id, p.full_name, p.national_id FROM db.customers c LEFT JOIN db.customers_pii p ON c.id = p.customer_id ORDER BY c.id LIMIT 50;
SELECT COUNT(*) AS total, COUNT(DISTINCT id) AS distinct_ids FROM db.customers;
SELECT COUNT(*) AS total, COUNT(DISTINCT customer_id) AS distinct_ids, SUM(CASE WHEN national_id IS NULL OR national_id = '' THEN 1 ELSE 0 END) AS missing_nid FROM db.customers_pii;
SELECT COUNT(*) AS matched FROM db.customers c JOIN db.customers_pii p ON c.id = p.customer_id;

